from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Remove spaces from the input string
    groups = []  # Initialize an empty list to store the separated groups
    group = ""  # Initialize an empty string to store the current group

    for char in paren_string:
        if char == "(":
            group += char
        elif char == ")":
            group += char
            groups.append(group)  # Append each group to the list
            group = ""  # Reset the current group

    return groups  # Return the list of separated groups

